import chess

white = {(0,2),(2,2),(4,2),(3,3),(5,3),(6,3)}
black = {(0,0),(2,0),(3,0),(5,0),(1,1),(5,1),(6,1)}

board = chess.Board()
for (c,r) in white:
    board.set_piece_at(chess.square(c, 7-r), chess.Piece(chess.PAWN, chess.WHITE))
for (c,r) in black:
    board.set_piece_at(chess.square(c, 7-r), chess.Piece(chess.PAWN, chess.BLACK))
board.turn = chess.WHITE

for m in board.legal_moves:
    b2 = board.copy()
    b2.push(m)
    # is white's king attacked by black pawns?
    king_sq = b2.king(chess.WHITE)
    attacked = b2.is_attacked_by(chess.BLACK, king_sq)
    status = []
    if b2.is_checkmate(): status.append("CHECKMATE")
    if b2.is_stalemate(): status.append("stalemate")
    if b2.is_check(): status.append("check")
    if attacked: status.append("king-attacked")
    print(board.san(m), m.uci(), status)
