import chess

white = {(0,2),(2,2),(4,2),(3,3),(5,3),(6,3)}
black = {(0,0),(2,0),(3,0),(5,0),(1,1),(5,1),(6,1)}

board = chess.Board()
for (c,r) in white:
    board.set_piece_at(chess.square(c, 7-r), chess.Piece(chess.PAWN, chess.WHITE))
for (c,r) in black:
    board.set_piece_at(chess.square(c, 7-r), chess.Piece(chess.PAWN, chess.BLACK))
board.turn = chess.WHITE

# verify each check: is it mate (any black reply leaves king attacked)?
for m in board.legal_moves:
    b2 = board.copy(); b2.push(m)
    if not b2.is_check(): continue
    mate = True
    for reply in b2.legal_moves:
        b3 = b2.copy(); b3.push(reply)
        if not b3.is_check():
            mate = False
            break
    print(board.san(m), m.uci(), "MATE" if mate else "check only")
